from ortools.sat.python import cp_model
import json

# Input data
ages = [3, 5, 7, 8, 10]
children = ['Bernice', 'Carl', 'Debby', 'Sammy', 'Ted']
countries = ['Ethiopia', 'Kazakhstan', 'Lithuania', 'Morocco', 'Yemen']
stories = ['burning bush', 'captivity', 'Moses’s youth', 'Passover', 'Ten Commandments']

# Model definition
model = cp_model.CpModel()

# Decision Variables
age_child = {}
for i in range(len(children)):
    for j in range(len(ages)):
        age_child[children[i], ages[j]] = model.NewBoolVar(f'{children[i]}_{ages[j]}')
child_country = {}
for i in range(len(children)):
    for j in range(len(countries)):
        child_country[children[i], countries[j]] = model.NewBoolVar(f'{children[i]}_{countries[j]}')
child_story = {}
for i in range(len(children)):
    for j in range(len(stories)):
        child_story[children[i], stories[j]] = model.NewBoolVar(f'{children[i]}_{stories[j]}')

# Constraints
for child in children:
    model.Add(sum(age_child[child, age] for age in ages) == 1)
for age in ages:
    model.Add(sum(age_child[child, age] for child in children) == 1)
for child in children:
    model.Add(sum(child_country[child, country] for country in countries) == 1)
for country in countries:
    model.Add(sum(child_country[child, country] for child in children) == 1)
for child in children:
    model.Add(sum(child_story[child, story] for story in stories) == 1)
for story in stories:
    model.Add(sum(child_story[child, story] for child in children) == 1)

# Constraint 1: Debby’s family is from Lithuania.
model.Add(child_country['Debby', 'Lithuania'] == 1)

# Constraint 2: The child who told the story of the Passover is two years older than Bernice.
for age in ages:
    if age + 2 in ages:
        model.Add(age_child['Bernice', age] + child_story[children[0], 'Passover'] <= 1)
        model.Add(age_child['Bernice', age] + child_story[children[1], 'Passover'] <= 1)
        model.Add(age_child['Bernice', age] + child_story[children[2], 'Passover'] <= 1)
        model.Add(age_child['Bernice', age] + child_story[children[3], 'Passover'] <= 1)
        model.Add(age_child['Bernice', age] + child_story[children[4], 'Passover'] <= 1)
        for child in children:
            if child != 'Bernice':
                model.Add(age_child[child, age + 2] + child_story[child, 'Passover'] <= 1)

# Constraint 3: The child whose family is from Yemen is younger than the child from the Ethiopian family.
for age1 in ages:
    for age2 in ages:
        if age1 < age2:
            for child1 in children:
                for child2 in children:
                    if child1 != child2:
                        model.Add(child_country[child1, 'Yemen'] + child_country[child2, 'Ethiopia'] + age_child[child1, age1] + age_child[child2, age2] <= 3)

# Constraint 4: The child from the Moroccan family is three years older than Ted.
for age in ages:
    if age + 3 in ages:
        model.Add(child_country['Ted', 'Morocco'] == 0)
        for child in children:
            if child != 'Ted':
                model.Add(child_country[child, 'Morocco'] + age_child['Ted', age] + age_child[child, age + 3] <= 2)

# Constraint 5: Sammy is three years older than the child who told the story of Moses’s youth in the house of the Pharaoh.
for age in ages:
    if age + 3 in ages:
        for child in children:
            if child != 'Sammy':
                model.Add(age_child['Sammy', age + 3] + child_story[child, "Moses’s youth"] <= 1)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    ages_list = []
    children_list = []
    countries_list = []
    stories_list = []
    for child in children:
        for age in ages:
            if solver.Value(age_child[child, age]) == 1:
                ages_list.append(ages.index(age) + 1)
    for child in children:
        children_list.append(children.index(child) + 1)
    for child in children:
        for country in countries:
            if solver.Value(child_country[child, country]) == 1:
                countries_list.append(countries.index(country) + 1)
    for child in children:
        for story in stories:
            if solver.Value(child_story[child, story]) == 1:
                stories_list.append(stories.index(story) + 1)
    solution = {
        'ages': ages_list,
        'children': children_list,
        'countries': countries_list,
        'stories': stories_list
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

