from ortools.sat.python import cp_model
import json

# Input data
jobs_data = [  # (job_id, task_id) -> (machine_id, duration)
    [(0, 3), (1, 2), (2, 2)],  # Job 0
    [(0, 2), (2, 1), (1, 4)],  # Job 1
    [(1, 4), (2, 3)]           # Job 2
]

# Model definition
model = cp_model.CpModel()

# Decision Variables
num_machines = max(max(machine_id for machine_id, _ in job) for job in jobs_data) + 1
num_jobs = len(jobs_data)
max_duration = sum(duration for job in jobs_data for _, duration in job)

task_starts = {}
for job_id, job in enumerate(jobs_data):
    for task_id, (machine_id, duration) in enumerate(job):
        task_starts[(job_id, task_id)] = model.NewIntVar(0, max_duration, f"task_start_{job_id}_{task_id}")

# Constraints
for job_id, job in enumerate(jobs_data):
    for task_id in range(len(job) - 1):
        model.Add(task_starts[(job_id, task_id + 1)] >= task_starts[(job_id, task_id)] + job[task_id][1])

machine_tasks = {}
for job_id, job in enumerate(jobs_data):
    for task_id, (machine_id, duration) in enumerate(job):
        if machine_id not in machine_tasks:
            machine_tasks[machine_id] = []
        machine_tasks[machine_id].append((task_starts[(job_id, task_id)], duration))

for machine_id, tasks in machine_tasks.items():
    model.AddNoOverlap(tasks)

# Objective function
makespan = model.NewIntVar(0, max_duration, "makespan")
for job_id, job in enumerate(jobs_data):
    model.Add(makespan >= task_starts[(job_id, len(job) - 1)] + job[-1][1])

model.Minimize(makespan)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'makespan': solver.Value(makespan)
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

