from ortools.sat.python import cp_model
import json

# Input data
game_data = [
    [2, 3, -1, 2, 2, -1, 2, 1],
    [-1, -1, 4, -1, -1, 4, -1, 2],
    [-1, -1, -1, -1, -1, -1, 4, -1],
    [-1, 5, -1, 6, -1, -1, -1, 2],
    [2, -1, -1, -1, 5, 5, -1, 2],
    [1, 3, 4, -1, -1, -1, 4, -1],
    [0, 1, -1, 4, -1, -1, -1, 3],
    [0, 1, 2, -1, 2, 3, -1, 2]
]

# Model definition
model = cp_model.CpModel()

# Decision Variables
mines = {}
for i in range(len(game_data)):
    for j in range(len(game_data[i])):
        if game_data[i][j] == -1:
            mines[(i, j)] = model.NewBoolVar(f'mine_{i}_{j}')

# Constraints
for i in range(len(game_data)):
    for j in range(len(game_data[i])):
        if game_data[i][j] != -1:
            adjacent_mines = 0
            for x in range(max(0, i-1), min(len(game_data), i+2)):
                for y in range(max(0, j-1), min(len(game_data[i]), j+2)):
                    if (x, y) != (i, j) and game_data[x][y] == -1:
                        adjacent_mines += mines[(x, y)]
            model.Add(adjacent_mines == game_data[i][j])

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'mines': [[False for _ in range(len(game_data[i]))] for i in range(len(game_data))]
    }
    for (i, j), mine in mines.items():
        solution['mines'][i][j] = solver.Value(mine)
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
