# Constraints
for i in range(n_boats):
    for j in range(n_boats):
        if i != j:
            # A guest boat cannot revisit a host
            model.Add(sum(visits[i*n_boats + j][k] for k in range(n_boats)) <= 1)

for i in range(n_boats):
    for j in range(n_boats):
        if i != j:
            # Guest crews cannot meet more than once
            model.Add(sum(visits[i*n_boats + j][k] for k in range(n_boats)) <= 1)

for i in range(n_boats):
    for j in range(n_periods):
        # A boat can only visit one host per period
        model.Add(sum(visits[i*n_boats + k][j] for k in range(n_boats)) <= 1)

